set search_path = pg_catalog;
select jsonb_build_object(
  'views', coalesce((select jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'options',c.reloptions,'definition_sha256',encode(sha256(convert_to(pg_get_viewdef(c.oid,true),'UTF8')),'hex')) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('v','m')), '[]'::jsonb),
  'private_functions', coalesce((select jsonb_agg(jsonb_build_object('name',p.proname,'owner',pg_get_userbyid(p.proowner),'arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'security_definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),'grants',(select jsonb_agg(jsonb_build_object('role',coalesce(r.rolname,'PUBLIC'),'privilege',x.privilege_type,'grantable',x.is_grantable) order by coalesce(r.rolname,'PUBLIC'),x.privilege_type) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x left join pg_roles r on r.oid=x.grantee)) order by p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.prokind='f' and not exists (select 1 from pg_depend dep where dep.objid=p.oid and dep.classid='pg_proc'::regclass and dep.deptype='e')), '[]'::jsonb),
  'schema_grants', coalesce((select jsonb_agg(jsonb_build_object('schema',n.nspname,'role',coalesce(r.rolname,'PUBLIC'),'privilege',x.privilege_type,'grantable',x.is_grantable) order by n.nspname,coalesce(r.rolname,'PUBLIC'),x.privilege_type) from pg_namespace n cross join lateral aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x left join pg_roles r on r.oid=x.grantee where n.nspname in ('public','private','extensions')), '[]'::jsonb),
  'storage_policies', coalesce((select jsonb_agg(jsonb_build_object('table',c.relname,'name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(select jsonb_agg(coalesce(r.rolname,'PUBLIC') order by coalesce(r.rolname,'PUBLIC')) from unnest(p.polroles) x(oid) left join pg_roles r on r.oid=x.oid),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by c.relname,p.polname) from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='storage' and c.relname='objects'), '[]'::jsonb)
) as catalog;
